'use server';

import { z } from 'zod';

const PlateEntryAssistantInputSchema = z.object({
  plate: z.string(),
});

export type PlateEntryAssistantInput = z.infer<
    typeof PlateEntryAssistantInputSchema
>;

const PlateEntryAssistantOutputSchema = z.object({
  validatedPlate: z.string(),
  isCorrected: z.boolean(),
  correctionMessage: z.string().optional(),
  predictedVehicleMake: z.string().optional(),
  isValid: z.boolean(),
});

export type PlateEntryAssistantOutput = z.infer<
    typeof PlateEntryAssistantOutputSchema
>;

function normalizePlate(plate: string): string {
  return plate.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
}

function isOldBrazilianPlate(plate: string): boolean {
  return /^[A-Z]{3}[0-9]{4}$/.test(plate);
}

function isMercosulPlate(plate: string): boolean {
  return /^[A-Z]{3}[0-9][A-Z][0-9]{2}$/.test(plate);
}

function getPlateFormat(plate: string): string | null {
  if (isOldBrazilianPlate(plate)) {
    return 'padrão antigo brasileiro';
  }

  if (isMercosulPlate(plate)) {
    return 'padrão Mercosul';
  }

  return null;
}

export async function plateEntryAssistant(
    input: PlateEntryAssistantInput
): Promise<PlateEntryAssistantOutput> {
  const parsedInput = PlateEntryAssistantInputSchema.parse(input);

  const originalPlate = parsedInput.plate;
  const normalizedPlate = normalizePlate(originalPlate);
  const format = getPlateFormat(normalizedPlate);

  const isCorrected = originalPlate !== normalizedPlate;

  if (!normalizedPlate) {
    return {
      validatedPlate: '',
      isCorrected,
      isValid: false,
      correctionMessage: 'Informe uma placa para validar.',
    };
  }

  if (!format) {
    return {
      validatedPlate: normalizedPlate,
      isCorrected,
      isValid: false,
      correctionMessage:
          'Formato inválido. Use o padrão antigo ABC1234 ou Mercosul ABC1D23.',
    };
  }

  return {
    validatedPlate: normalizedPlate,
    isCorrected,
    isValid: true,
    correctionMessage: isCorrected
        ? `A placa foi normalizada para ${normalizedPlate}.`
        : `Placa válida no ${format}.`,
  };
}